/* ===================================================
   Particle Cosmos - Global Styles & Design System
   =================================================== */

:root {
  --bg-primary: #070913;
  --bg-glass: rgba(15, 23, 42, 0.75);
  --bg-glass-card: rgba(30, 41, 59, 0.65);
  --bg-glass-hover: rgba(51, 65, 85, 0.75);
  --border-glass: rgba(255, 255, 255, 0.12);
  --border-focus: rgba(99, 102, 241, 0.8);
  --text-main: #f8fafc;
  --text-sub: #94a3b8;
  --text-dim: #64748b;
  --accent-aurora: #10b981;
  --accent-neon: #ec4899;
  --accent-sakura: #f472b6;
  --accent-cosmic: #6366f1;
  --accent-purple: #a855f7;
  --accent-gold: #f59e0b;
  --shadow-glow: 0 0 25px rgba(99, 102, 241, 0.35);
  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --radius-full: 9999px;
  --transition: all 0.25s cubic-bezier(0.16, 1, 0.3, 1);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  user-select: none;
}

html,
body {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background-color: var(--bg-primary);
  color: var(--text-main);
  font-family: var(--font-family);
  touch-action: none;
}

/* Accessibility focus outline */
button:focus-visible,
input:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 2px;
}

/* ---------------------------------------------
   App Container & Canvas Layout
   --------------------------------------------- */
.app-wrapper {
  position: relative;
  width: 100vw;
  height: 100vh;
  overflow: hidden;
  background: radial-gradient(circle at 50% 50%, #0d1224 0%, #070913 100%);
}

.canvas-container {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  z-index: 1;
}

.particle-canvas {
  display: block;
  width: 100%;
  height: 100%;
  cursor: crosshair;
}

/* ---------------------------------------------
   UI Overlay Layer
   --------------------------------------------- */
.ui-layer {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 10;
  overflow: hidden;
}

/* HUD Info (Stats display) */
.hud-stats {
  position: absolute;
  top: 20px;
  left: 20px;
  pointer-events: auto;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 8px 16px;
  background: var(--bg-glass);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid var(--border-glass);
  border-radius: var(--radius-full);
  font-size: 13px;
  font-weight: 500;
  color: var(--text-sub);
  letter-spacing: 0.03em;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  transition: var(--transition);
}

.hud-stats span {
  color: var(--text-main);
  font-weight: 600;
}

.hud-divider {
  width: 1px;
  height: 12px;
  background: rgba(255, 255, 255, 0.2);
}

/* Floating Instruction Toast */
.help-toast {
  position: absolute;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  pointer-events: none;
  padding: 10px 20px;
  background: rgba(15, 23, 42, 0.85);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: var(--radius-full);
  color: var(--text-main);
  font-size: 13px;
  font-weight: 500;
  text-align: center;
  white-space: nowrap;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5), 0 0 15px rgba(99, 102, 241, 0.2);
  animation: floatBounce 3s ease-in-out infinite;
}

@keyframes floatBounce {
  0%, 100% {
    transform: translate(-50%, 0);
  }
  50% {
    transform: translate(-50%, -6px);
  }
}

/* Controls Toggle Button (FAB) */
.controls-toggle-btn {
  position: absolute;
  top: 20px;
  right: 20px;
  pointer-events: auto;
  width: 44px;
  height: 44px;
  border-radius: var(--radius-full);
  background: var(--bg-glass);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid var(--border-glass);
  color: var(--text-main);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.35);
  transition: var(--transition);
  z-index: 15;
}

.controls-toggle-btn:hover {
  background: var(--bg-glass-hover);
  border-color: rgba(255, 255, 255, 0.25);
  box-shadow: var(--shadow-glow);
  transform: scale(1.05);
}

.controls-toggle-btn:active {
  transform: scale(0.95);
}

/* ---------------------------------------------
   Control Panel (Glassmorphism Sidebar)
   --------------------------------------------- */
.controls-panel {
  position: absolute;
  top: 0;
  right: 0;
  width: 360px;
  max-width: 90vw;
  height: 100%;
  pointer-events: auto;
  background: var(--bg-glass);
  backdrop-filter: blur(24px);
  -webkit-backdrop-filter: blur(24px);
  border-left: 1px solid var(--border-glass);
  box-shadow: -10px 0 40px rgba(0, 0, 0, 0.6);
  padding: 24px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 20px;
  transform: translateX(0);
  transition: transform 0.35s cubic-bezier(0.16, 1, 0.3, 1);
  z-index: 25;
}

.controls-panel.closed {
  transform: translateX(105%);
}

/* Panel Header */
.controls-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--border-glass);
}

.controls-title {
  font-size: 17px;
  font-weight: 700;
  letter-spacing: 0.05em;
  color: #fff;
  display: flex;
  align-items: center;
  gap: 8px;
}

.controls-close-btn {
  width: 32px;
  height: 32px;
  border-radius: var(--radius-sm);
  background: transparent;
  border: 1px solid transparent;
  color: var(--text-sub);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: var(--transition);
}

.controls-close-btn:hover {
  background: rgba(255, 255, 255, 0.1);
  color: var(--text-main);
  border-color: var(--border-glass);
}

/* ---------------------------------------------
   Control Groups & Form Elements
   --------------------------------------------- */
.control-group {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.control-label {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 13px;
  font-weight: 600;
  color: var(--text-sub);
}

.control-label span {
  font-family: monospace;
  font-size: 12px;
  color: var(--text-main);
  background: rgba(255, 255, 255, 0.08);
  padding: 2px 8px;
  border-radius: var(--radius-sm);
}

/* Sliders */
.control-slider {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 6px;
  border-radius: 3px;
  background: rgba(255, 255, 255, 0.12);
  outline: none;
  cursor: pointer;
  transition: var(--transition);
}

.control-slider:hover {
  background: rgba(255, 255, 255, 0.2);
}

.control-slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: #ffffff;
  box-shadow: 0 0 10px var(--border-focus);
  cursor: pointer;
  transition: transform 0.15s ease, box-shadow 0.15s ease;
}

.control-slider::-moz-range-thumb {
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: #ffffff;
  border: none;
  box-shadow: 0 0 10px var(--border-focus);
  cursor: pointer;
  transition: transform 0.15s ease, box-shadow 0.15s ease;
}

.control-slider::-webkit-slider-thumb:hover {
  transform: scale(1.15);
  box-shadow: 0 0 14px rgba(255, 255, 255, 0.9);
}

/* Theme Selector Grid */
.color-theme-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 8px;
}

.theme-btn {
  aspect-ratio: 1;
  border-radius: var(--radius-md);
  border: 2px solid transparent;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  font-size: 10px;
  font-weight: 600;
  color: #fff;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.8);
  position: relative;
  overflow: hidden;
  transition: var(--transition);
  padding: 4px;
}

.theme-btn:nth-child(1) { --theme-accent: var(--accent-aurora); }
.theme-btn:nth-child(2) { --theme-accent: var(--accent-neon); }
.theme-btn:nth-child(3) { --theme-accent: var(--accent-sakura); }
.theme-btn:nth-child(4) { --theme-accent: var(--accent-cosmic); }
.theme-btn:nth-child(5) { --theme-accent: var(--accent-gold); }

.theme-btn:hover {
  transform: translateY(-2px);
  filter: brightness(1.15);
  box-shadow: 0 4px 12px var(--theme-accent, rgba(255, 255, 255, 0.2));
}

.theme-btn-active {
  border-color: #ffffff;
  box-shadow: 0 0 15px var(--theme-accent, rgba(255, 255, 255, 0.45));
  transform: scale(1.05);
}

/* Mode Selector */
.mode-selector {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 8px;
}

.mode-btn {
  padding: 10px 12px;
  border-radius: var(--radius-md);
  background: var(--bg-glass-card);
  border: 1px solid var(--border-glass);
  color: var(--text-sub);
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  text-align: center;
  transition: var(--transition);
}

.mode-btn:hover {
  background: var(--bg-glass-hover);
  color: var(--text-main);
  border-color: rgba(255, 255, 255, 0.2);
}

.mode-btn-active {
  background: linear-gradient(135deg, rgba(99, 102, 241, 0.35), rgba(168, 85, 247, 0.35));
  border-color: var(--accent-purple);
  color: #ffffff;
  box-shadow: var(--shadow-glow);
}

/* Action Buttons (Burst, Reset) */
.action-btn-group {
  display: flex;
  gap: 10px;
  margin-top: 8px;
}

.action-btn {
  flex: 1;
  padding: 12px 14px;
  border-radius: var(--radius-md);
  background: var(--bg-glass-card);
  border: 1px solid var(--border-glass);
  color: var(--text-main);
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  transition: var(--transition);
}

.action-btn:hover {
  background: var(--bg-glass-hover);
  border-color: rgba(255, 255, 255, 0.25);
  transform: translateY(-1px);
}

.action-btn:active {
  transform: translateY(1px);
}

.action-btn-primary {
  background: linear-gradient(135deg, var(--accent-cosmic) 0%, var(--accent-purple) 100%);
  border: none;
  color: #ffffff;
  box-shadow: 0 4px 18px rgba(99, 102, 241, 0.4);
}

.action-btn-primary:hover {
  background: linear-gradient(135deg, #4f46e5 0%, #9333ea 100%);
  box-shadow: 0 6px 24px rgba(168, 85, 247, 0.5);
  transform: translateY(-1px);
}

/* Footer note */
.controls-footer-note {
  margin-top: auto;
  padding-top: 16px;
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  color: var(--text-dim);
}

/* ---------------------------------------------
   Scrollbar & Responsive Optimizations
   --------------------------------------------- */
.controls-panel::-webkit-scrollbar {
  width: 6px;
}

.controls-panel::-webkit-scrollbar-track {
  background: transparent;
}

.controls-panel::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.15);
  border-radius: 3px;
}

.controls-panel::-webkit-scrollbar-thumb:hover {
  background: rgba(255, 255, 255, 0.3);
}

@media (max-width: 480px) {
  .controls-panel {
    width: 100%;
    max-width: 100vw;
    padding: 16px;
    z-index: 30;
  }

  .controls-header {
    padding-bottom: 12px;
  }

  .hud-stats {
    top: 12px;
    left: 12px;
    font-size: 11px;
    padding: 6px 12px;
  }

  .controls-toggle-btn {
    top: 12px;
    right: 12px;
    width: 40px;
    height: 40px;
    z-index: 20;
  }

  .help-toast {
    bottom: 16px;
    font-size: 11px;
    padding: 8px 14px;
    max-width: 90vw;
    white-space: normal;
  }
}

export type ParticleMode = 'follow' | 'vortex' | 'explode' | 'stream';

export type ColorTheme = 'aurora' | 'neon' | 'sakura' | 'cosmic' | 'gold';

export interface ParticleConfig {
  count: number;
  speed: number;
  size: number;
  trailLength: number;
  attractionStrength: number;
  mode: ParticleMode;
  theme: ColorTheme;
  glow: boolean;
}

export type NumericParticleConfigKey = {
  [K in keyof ParticleConfig]: ParticleConfig[K] extends number ? K : never;
}[keyof ParticleConfig];

export interface ParticleItem {
  x: number;
  y: number;
  vx: number;
  vy: number;
  size: number;
  baseSize: number;
  color: string;
  alpha: number;
  life: number;
  maxLife: number;
}

export type ConfigUpdateHandler = (newConfig: Partial<ParticleConfig>) => void;

export interface ControlPanelProps {
  config: ParticleConfig;
  onChangeConfig: ConfigUpdateHandler;
  onTriggerBurst: () => void;
  isPanelOpen: boolean;
  onTogglePanel: () => void;
}

export interface PresetOption {
  id: string;
  name: string;
  description: string;
  config: Partial<ParticleConfig>;
}

export interface CanvasDimensions {
  width: number;
  height: number;
}

export interface PointerState {
  x: number;
  y: number;
  isActive: boolean;
  lastActiveTime: number;
}

