import React, { useEffect, useRef, useCallback } from 'react';
import { ParticleConfig, ParticleItem, PointerState } from '../types';
import { THEME_PALETTES } from '../constants';

interface ParticleCanvasProps {
  config: ParticleConfig;
  burstTriggerCount: number;
  onFpsUpdate?: (fps: number) => void;
}

const ParticleCanvas: React.FC<ParticleCanvasProps> = ({
  config,
  burstTriggerCount,
  onFpsUpdate,
}) => {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const containerRef = useRef<HTMLDivElement | null>(null);

  // アニメーションおよびパーティクル状態への参照
  const particlesRef = useRef<ParticleItem[]>([]);
  const pointerRef = useRef<PointerState>({
    x: 0,
    y: 0,
    isActive: false,
    lastActiveTime: 0,
  });
  const configRef = useRef<ParticleConfig>(config);
  configRef.current = config;

  const animationFrameIdRef = useRef<number | null>(null);
  const lastTimeRef = useRef<number>(0);
  const fpsFrameCountRef = useRef<number>(0);
  const fpsLastTimeRef = useRef<number>(0);
  const prevBurstTriggerRef = useRef<number>(burstTriggerCount);

  // パーティクル初期化・再生成ヘルパー
  const createParticle = useCallback(
    (
      width: number,
      height: number,
      originX?: number,
      originY?: number,
      customSpeed?: number
    ): ParticleItem => {
      const palette = THEME_PALETTES[configRef.current.theme] || THEME_PALETTES.aurora;
      const color = palette[Math.floor(Math.random() * palette.length)];
      const baseSize = Math.max(0.8, configRef.current.size * (0.6 + Math.random() * 0.8));

      const x = originX !== undefined ? originX : Math.random() * width;
      const y = originY !== undefined ? originY : Math.random() * height;

      const angle = Math.random() * Math.PI * 2;
      const velocityMagnitude =
        customSpeed !== undefined
          ? customSpeed
          : (0.4 + Math.random() * 1.2) * configRef.current.speed * 60;

      return {
        x,
        y,
        vx: Math.cos(angle) * velocityMagnitude,
        vy: Math.sin(angle) * velocityMagnitude,
        size: baseSize,
        baseSize,
        color,
        alpha: 0.3 + Math.random() * 0.7,
        life: 0,
        maxLife: 200 + Math.random() * 300,
      };
    },
    []
  );

  // 指定座標でのエネルギー爆散生成
  const triggerBurstAt = useCallback(
    (cx: number, cy: number, count: number = 70) => {
      if (!canvasRef.current) return;
      const rect = canvasRef.current.getBoundingClientRect();
      const palette = THEME_PALETTES[configRef.current.theme] || THEME_PALETTES.aurora;

      for (let i = 0; i < count; i++) {
        const angle = Math.random() * Math.PI * 2;
        const speed = (2 + Math.random() * 8) * configRef.current.speed * 60;
        const baseSize = configRef.current.size * (1.0 + Math.random() * 1.5);

        particlesRef.current.push({
          x: cx,
          y: cy,
          vx: Math.cos(angle) * speed,
          vy: Math.sin(angle) * speed,
          size: baseSize,
          baseSize,
          color: palette[Math.floor(Math.random() * palette.length)],
          alpha: 1.0,
          life: 0,
          maxLife: 80 + Math.random() * 60,
        });
      }

      // 粒子過多防止の安全策
      const maxAllowed = configRef.current.count + 200;
      if (particlesRef.current.length > maxAllowed) {
        particlesRef.current.splice(0, particlesRef.current.length - maxAllowed);
      }
    },
    []
  );

  // burstTriggerCount の外部変化（Spaceキー、爆発ボタン）を検知
  useEffect(() => {
    if (burstTriggerCount > prevBurstTriggerRef.current) {
      prevBurstTriggerRef.current = burstTriggerCount;
      if (canvasRef.current) {
        const rect = canvasRef.current.getBoundingClientRect();
        const burstX = pointerRef.current.isActive
          ? pointerRef.current.x
          : rect.width / 2;
        const burstY = pointerRef.current.isActive
          ? pointerRef.current.y
          : rect.height / 2;
        triggerBurstAt(burstX, burstY, 100);
      }
    }
  }, [burstTriggerCount, triggerBurstAt]);

  // パーティクル配列の要素数とテーマ色を同期
  useEffect(() => {
    if (!canvasRef.current) return;
    const rect = canvasRef.current.getBoundingClientRect();
    const currentParticles = particlesRef.current;
    const targetCount = config.count;

    if (currentParticles.length < targetCount) {
      const diff = targetCount - currentParticles.length;
      for (let i = 0; i < diff; i++) {
        currentParticles.push(createParticle(rect.width, rect.height));
      }
    } else if (currentParticles.length > targetCount) {
      particlesRef.current = currentParticles.slice(0, targetCount);
    }

    // テーマ変更時に色を再割り当て
    const palette = THEME_PALETTES[config.theme] || THEME_PALETTES.aurora;
    particlesRef.current.forEach((p) => {
      p.color = palette[Math.floor(Math.random() * palette.length)];
      p.baseSize = Math.max(0.8, config.size * (0.6 + Math.random() * 0.8));
    });
  }, [config.count, config.theme, config.size, createParticle]);

  // Canvas初期化とリサイズ・描画ループ
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d', { alpha: false });
    if (!ctx) return;

    let resizeRafId: number | null = null;

    const handleResize = () => {
      if (resizeRafId !== null) {
        cancelAnimationFrame(resizeRafId);
      }
      resizeRafId = requestAnimationFrame(() => {
        const container = containerRef.current || canvas.parentElement;
        const width = container ? container.clientWidth : window.innerWidth;
        const height = container ? container.clientHeight : window.innerHeight;
        const dpr = Math.min(window.devicePixelRatio || 1, 2);

        canvas.width = Math.floor(width * dpr);
        canvas.height = Math.floor(height * dpr);
        canvas.style.width = `${width}px`;
        canvas.style.height = `${height}px`;

        ctx.setTransform(1, 0, 0, 1, 0, 0);
        ctx.scale(dpr, dpr);

        // 背景を完全クリア
        ctx.fillStyle = '#070913';
        ctx.fillRect(0, 0, width, height);

        // 初期パーティクル生成（まだ空の場合）
        if (particlesRef.current.length === 0) {
          const initialList: ParticleItem[] = [];
          for (let i = 0; i < configRef.current.count; i++) {
            initialList.push(createParticle(width, height));
          }
          particlesRef.current = initialList;
        }
      });
    };

    handleResize();
    window.addEventListener('resize', handleResize);

    // 描画メインループ
    const renderLoop = (time: number) => {
      if (!lastTimeRef.current) {
        lastTimeRef.current = time;
        fpsLastTimeRef.current = time;
      }

      // デルタタイム算出（秒単位、上限0.1sでブラウザタブ切り替え時のスパイク防止）
      const dt = Math.min((time - lastTimeRef.current) / 1000, 0.1);
      lastTimeRef.current = time;

      // FPS計測
      fpsFrameCountRef.current++;
      if (time - fpsLastTimeRef.current >= 1000) {
        const calculatedFps = Math.round(
          (fpsFrameCountRef.current * 1000) / (time - fpsLastTimeRef.current)
        );
        if (onFpsUpdate) {
          onFpsUpdate(calculatedFps);
        }
        fpsFrameCountRef.current = 0;
        fpsLastTimeRef.current = time;
      }

      const rect = canvas.getBoundingClientRect();
      const width = rect.width;
      const height = rect.height;

      const currentConfig = configRef.current;
      const pointer = pointerRef.current;

      // トレイル（残像）フェード描画
      // trailLength: 0.05(長い軌跡) 〜 0.5(クリアな軌跡)
      const fadeAlpha = Math.max(0.04, Math.min(0.6, currentConfig.trailLength));
      ctx.fillStyle = `rgba(7, 9, 19, ${fadeAlpha})`;
      ctx.fillRect(0, 0, width, height);

      // 自律動作時の仮想ターゲット座標算出（ポインタ非操作時）
      const timeSec = time * 0.001;
      let targetX = pointer.x;
      let targetY = pointer.y;

      const isPointerInactive =
        !pointer.isActive && time - pointer.lastActiveTime > 2500;
      if (isPointerInactive) {
        const radiusX = width * 0.35;
        const radiusY = height * 0.3;
        targetX = width / 2 + Math.cos(timeSec * 0.8) * radiusX;
        targetY = height / 2 + Math.sin(timeSec * 1.2) * radiusY;
      }

      const speedFactor = currentConfig.speed;
      const attraction = currentConfig.attractionStrength;
      const mode = currentConfig.mode;
      const particles = particlesRef.current;

      for (let i = particles.length - 1; i >= 0; i--) {
        const p = particles[i];

        const dx = targetX - p.x;
        const dy = targetY - p.y;
        const distSq = dx * dx + dy * dy;
        const dist = Math.sqrt(distSq) || 1;

        // モード別物理演算
        switch (mode) {
          case 'follow': {
            // スムーズな引力追尾 + わずかな周回力
            const force = (Math.min(dist, 400) / 400) * attraction * 90;
            const nx = dx / dist;
            const ny = dy / dist;
            p.vx += (nx * force - p.vx * 1.5) * dt * speedFactor;
            p.vy += (ny * force - p.vy * 1.5) * dt * speedFactor;
            break;
          }
          case 'vortex': {
            // 渦潮・ブラックホール引力（接線方向のトルク + 中心引力）
            const force = Math.max(0.1, 1 - dist / (width * 0.6)) * attraction * 140;
            const nx = dx / dist;
            const ny = dy / dist;
            const tangentX = -ny;
            const tangentY = nx;

            p.vx += (nx * force * 0.6 + tangentX * force * 1.2 - p.vx * 1.2) * dt * speedFactor;
            p.vy += (ny * force * 0.6 + tangentY * force * 1.2 - p.vy * 1.2) * dt * speedFactor;
            break;
          }
          case 'explode': {
            // 接触時に外側へ強く跳ね返る反発力場
            const radius = 220;
            if (dist < radius) {
              const repel = ((radius - dist) / radius) * attraction * 280;
              p.vx -= (dx / dist) * repel * dt * speedFactor;
              p.vy -= (dy / dist) * repel * dt * speedFactor;
            } else {
              // 遠くではゆっくり中心へ回帰
              p.vx += ((dx / dist) * 20 - p.vx * 0.5) * dt * speedFactor;
              p.vy += ((dy / dist) * 20 - p.vy * 0.5) * dt * speedFactor;
            }
            break;
          }
          case 'stream': {
            // 一方向（右斜め下）に流れる宇宙線ストリーム + ポインタ近接時の重力レンズ湾曲
            p.vx += (70 * speedFactor - p.vx * 0.6) * dt;
            p.vy += (40 * speedFactor - p.vy * 0.6) * dt;

            if (dist < 300) {
              const bend = (1 - dist / 300) * attraction * 120;
              p.vx += (dx / dist) * bend * dt;
              p.vy += (dy / dist) * bend * dt;
            }
            break;
          }
        }

        // 速度上限の設定
        const maxV = 600 * speedFactor;
        const currentV = Math.sqrt(p.vx * p.vx + p.vy * p.vy);
        if (currentV > maxV) {
          p.vx = (p.vx / currentV) * maxV;
          p.vy = (p.vy / currentV) * maxV;
        }

        // 座標更新
        p.x += p.vx * dt;
        p.y += p.vy * dt;

        // 画面外ワープ・跳ね返り
        const margin = 20;
        if (mode === 'stream') {
          if (p.x > width + margin) p.x = -margin;
          if (p.x < -margin) p.x = width + margin;
          if (p.y > height + margin) p.y = -margin;
          if (p.y < -margin) p.y = height + margin;
        } else {
          if (p.x < 0) {
            p.x = 0;
            p.vx *= -0.7;
          } else if (p.x > width) {
            p.x = width;
            p.vx *= -0.7;
          }
          if (p.y < 0) {
            p.y = 0;
            p.vy *= -0.7;
          } else if (p.y > height) {
            p.y = height;
            p.vy *= -0.7;
          }
        }

        p.life += dt * 60;
        if (p.life > p.maxLife && particles.length > currentConfig.count) {
          particles.splice(i, 1);
          continue;
        }

        // パーティクル描画
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);

        if (currentConfig.glow) {
          ctx.shadowBlur = p.size * 2.5;
          ctx.shadowColor = p.color;
        } else {
          ctx.shadowBlur = 0;
        }

        ctx.fillStyle = p.color;
        ctx.globalAlpha = p.alpha;
        ctx.fill();
      }

      ctx.globalAlpha = 1.0;
      ctx.shadowBlur = 0;

      animationFrameIdRef.current = requestAnimationFrame(renderLoop);
    };

    animationFrameIdRef.current = requestAnimationFrame(renderLoop);

    return () => {
      if (resizeRafId !== null) cancelAnimationFrame(resizeRafId);
      if (animationFrameIdRef.current !== null) {
        cancelAnimationFrame(animationFrameIdRef.current);
      }
      window.removeEventListener('resize', handleResize);
    };
  }, [createParticle, onFpsUpdate]);

  // ポインタ・タッチイベントハンドラ
  const handlePointerMove = (e: React.PointerEvent<HTMLCanvasElement>) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const rect = canvas.getBoundingClientRect();
    pointerRef.current = {
      x: e.clientX - rect.left,
      y: e.clientY - rect.top,
      isActive: true,
      lastActiveTime: performance.now(),
    };
  };

  const handlePointerDown = (e: React.PointerEvent<HTMLCanvasElement>) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const rect = canvas.getBoundingClientRect();
    const px = e.clientX - rect.left;
    const py = e.clientY - rect.top;
    pointerRef.current = {
      x: px,
      y: py,
      isActive: true,
      lastActiveTime: performance.now(),
    };
    triggerBurstAt(px, py, 60);
  };

  const handlePointerUp = () => {
    pointerRef.current.isActive = false;
    pointerRef.current.lastActiveTime = performance.now();
  };

  const handlePointerLeave = () => {
    pointerRef.current.isActive = false;
    pointerRef.current.lastActiveTime = performance.now();
  };

  return (
    <div ref={containerRef} className="canvas-container">
      <canvas
        ref={canvasRef}
        className="particle-canvas"
        onPointerMove={handlePointerMove}
        onPointerDown={handlePointerDown}
        onPointerUp={handlePointerUp}
        onPointerLeave={handlePointerLeave}
        onPointerCancel={handlePointerLeave}
      />
    </div>
  );
};

