import { useState, useCallback, useEffect } from 'react';
import { Sliders } from 'lucide-react';
import { ParticleConfig } from './types';
import { DEFAULT_CONFIG, PARTICLE_MODES, THEME_OPTIONS } from './constants';
import ParticleCanvas from './components/ParticleCanvas';
import ControlPanel from './components/ControlPanel';
import './index.css';

const App = () => {
  const [config, setConfig] = useState<ParticleConfig>(DEFAULT_CONFIG);
  const [isPanelOpen, setIsPanelOpen] = useState(false);
  const [burstCount, setBurstCount] = useState(0);
  const [fps, setFps] = useState(60);
  const [showToast, setShowToast] = useState(true);

  const handleChangeConfig = useCallback((newConfig: Partial<ParticleConfig>) => {
    setConfig((prev) => ({ ...prev, ...newConfig }));
  }, []);

  const handleTriggerBurst = useCallback(() => {
    setBurstCount((prev) => prev + 1);
  }, []);

  const handleTogglePanel = useCallback(() => {
    setIsPanelOpen((prev) => !prev);
  }, []);

  const handleFpsUpdate = useCallback((newFps: number) => {
    setFps(newFps);
  }, []);

  const handleDismissToast = useCallback(() => {
    setShowToast(false);
  }, []);

  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (
        event.target instanceof HTMLInputElement ||
        event.target instanceof HTMLTextAreaElement
      ) {
        return;
      }

      if (event.code === 'Space') {
        event.preventDefault();
        handleTriggerBurst();
        setShowToast(false);
      } else if (event.key === 'Escape') {
        event.preventDefault();
        setIsPanelOpen((prev) => !prev);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [handleTriggerBurst]);

  const currentModeInfo = PARTICLE_MODES.find((m) => m.id === config.mode);
  const currentThemeInfo = THEME_OPTIONS.find((t) => t.id === config.theme);

  return (
    <div className="app-wrapper" onPointerDown={handleDismissToast}>
      {/* メインCanvasパーティクル描画レイヤー */}
      <ParticleCanvas
        config={config}
        burstTriggerCount={burstCount}
        onFpsUpdate={handleFpsUpdate}
      />

      {/* UI オーバーレイ */}
      <div className="ui-layer">
        {/* HUD 情報表示 */}
        <div className="hud-stats">
          <span>{config.count}</span> 粒子
          <div className="hud-divider" />
          <span>{fps}</span> FPS
          <div className="hud-divider" />
          <span>{currentThemeInfo?.label}</span> / {currentModeInfo?.label}
        </div>

        {/* コントロール開閉ボタン */}
        <button
          type="button"
          className="controls-toggle-btn"
          onClick={handleTogglePanel}
          title={isPanelOpen ? 'コントロールを閉じる' : '設定パネルを開く'}
          aria-label={isPanelOpen ? 'コントロールを閉じる' : '設定パネルを開く'}
        >
          <Sliders size={20} />
        </button>

        {/* 初回・ガイダンストースト */}
        {showToast && (
          <div className="help-toast">
            ✨ 画面上でマウスを動かしたりタップしてみてください [Space: 爆発 / Esc: パネル]
          </div>
        )}
      </div>

      {/* 設定パネル */}
      <ControlPanel
        config={config}
        onChangeConfig={handleChangeConfig}
        onTriggerBurst={handleTriggerBurst}
        isPanelOpen={isPanelOpen}
        onTogglePanel={handleTogglePanel}
      />
    </div>
  );
};

export default App;
